import{_ as e,A as i,q as a,B as n,aV as o,H as t}from"./chunks/framework.B_e8lQlv.js";const c=JSON.parse('{"title":"Tailwind CSS","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/project/tailwindcss.md","filePath":"en/guide/project/tailwindcss.md"}');const d=e({name:"en/guide/project/tailwindcss.md"},[["render",function(e,c,d,s,l,r){const u=i("NolebaseGitContributors"),h=i("NolebaseGitChangelog");return a(),n("div",null,[c[0]||(c[0]=o('<h1 id="tailwind-css" tabindex="-1">Tailwind CSS <a class="header-anchor" href="#tailwind-css" aria-label="Permalink to &quot;Tailwind CSS&quot;">​</a></h1><p><a href="https://tailwindcss.com/" target="_blank" rel="noreferrer">Tailwind CSS</a> is a utility-first CSS framework for quickly building custom designs. The current project uses <strong>Tailwind CSS v4</strong>.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>The project no longer maintains Tailwind through <code>tailwind.config.*</code> files. Theme definitions and scan scope are now managed through CSS and the shared Vite configuration.</p><ul><li>Theme entry: <code>internal/tailwind-config/src/theme.css</code></li><li>Vite integration: <code>internal/vite-config</code></li></ul><p>In <code>global.css</code>, you will see the Tailwind CSS v4 directives currently used by the project, such as:</p><ul><li><code>@source</code></li><li><code>@custom-variant</code></li><li><code>@theme</code></li><li><code>@theme inline</code></li><li><code>@utility</code></li></ul><h2 id="how-packages-use-tailwind-css" tabindex="-1">How Packages Use Tailwind CSS <a class="header-anchor" href="#how-packages-use-tailwind-css" aria-label="Permalink to &quot;How Packages Use Tailwind CSS&quot;">​</a></h2><p>The project does not decide whether Tailwind CSS is enabled based on whether a package contains <code>tailwind.config.mjs</code>.</p><p>Apps and packages share <code>@vben/vite-config</code>, which integrates <code>@tailwindcss/vite</code>. The Tailwind scan scope is managed centrally in <code>@vben/tailwind-config</code>, backed by <code>internal/tailwind-config/src/theme.css</code>.</p><div class="tip custom-block"><p class="custom-block-title">Notes on using Tailwind CSS in packages</p><p>If you are building a pure SDK package and do not need Tailwind CSS, you do not need to add any legacy <code>tailwind.config.*</code> file.</p></div><h2 id="apply-in-vue-sfcs" tabindex="-1"><code>@apply</code> in Vue SFCs <a class="header-anchor" href="#apply-in-vue-sfcs" aria-label="Permalink to &quot;`@apply` in Vue SFCs&quot;">​</a></h2><p>The project applies a shared handling layer for <code>@apply</code> inside Vue single-file components. The related logic is located at:</p><ul><li><code>internal/vite-config/src/plugins/tailwind-reference.ts</code></li></ul><p>When component styles use <code>@apply</code>, <code>@reference &quot;@vben/tailwind-config/theme&quot;</code> is injected automatically in most cases.</p>',15)),t(u),t(h)])}]]);export{c as __pageData,d as default};
